entries[310422] = { ["name"] = "Unnachgiebiger Schutz", ["text"] = "Azerit Essenz\nVerbündete innerhalb von 15 Metern erhalten alle 10 Sek. einen Schild, der [ 113 * (1 + Vielseitigkeit)] Schaden absorbiert. Dieser Effekt ist bis zu einem Maximum von [ 848 * (1 + Vielseitigkeit) * (1.2)] stapelbar.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
entries[310425] = { ["name"] = "Wächtersphäre", ["text"] = "Azerit Essenz\nKanalisiert (Wirken in 4 sek.) 3 min Abklingzeit\nEntsendet 12 Schutzsphären, die sich 4 Sek. lang nach außen bewegen. Der erste von ihnen getroffene Verbündete erhält einen Schild, der 10 Sek. lang 1840 Schaden absorbiert.\n\nJedes Mal, wenn Ihr eine Schutzsphäre entsendet, erhaltet Ihr einen Absorptionsschild in Höhe von 2% Eurer maximalen Gesundheit." }
entries[310426] = { ["name"] = "Unnachgiebiger Schutz", ["text"] = "Azerit Essenz\nVerbündete innerhalb von 15 Metern erhalten alle 10 Sek. einen Schild, der [ 113 * (1 + Vielseitigkeit)] Schaden absorbiert. Dieser Effekt ist bis zu [ 848 * (1 + Vielseitigkeit) * (1.2)]-mal stapelbar.\n\nVon 'Unnachgiebiger Schutz' geschützte Ziele erleiden 3% weniger Schaden.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
