entries[310478] = { ["name"] = "Leerenmiasma", ["text"] = "Unbegrenzte Reichweite\nSofort\nDas Tentakel von Drest'agath erzeugt innerhalb von 12 Metern eine Miasmawolke, die allen Gegnern darin alle 3 Sek. 4690 Schattenschaden zufügt. Gegner können Ziele im Effektbereich von ' Leerenmiasma ' nicht von außerhalb anvisieren und umgekehrt." }
