entries[310484] = { ["name"] = "Nussknackergranate", ["text"] = "Wirken in 2 sek.\nReagenzien:\nHandvoll Laestritbolzen (3), Poröses Scheuermittel (2), Laestriterz\nBeruf:\nIngenieurskunst der Schattenlande (10)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n30\n\n(2)\nBenutzen: Fügt allen Gegnern in einem Radius von 5 Metern 13939 Naturschaden zu. (5 Min Abklingzeit)\n51" }
entries[310485] = { ["name"] = "Schattenlandmine", ["text"] = "Wirken in 2 sek.\nReagenzien:\nHandvoll Laestritbolzen (5), Poröses Scheuermittel (3), Laestriterz (3)\nBeruf:\nIngenieurskunst der Schattenlande (20)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n75\n\n(2)\nBenutzen: Platziert eine Mine auf dem Boden, die explodiert, wenn ein Gegner auf sie tritt. Dies fügt allen Gegnern innerhalb eines Radius von 5 Metern 13939 Schattenschaden zu und stößt sie zurück. (5 Min Abklingzeit)\nBenötigt Ingenieurskunst der Schattenlande\n(1)" }
entries[310486] = { ["name"] = "Bombenbolawerfer", ["text"] = "Wirken in 2 sek.\nReagenzien:\nNussknackergranate (3), Wurmdurchsetztes Getriebe , Poröses Scheuermittel (5), Zwielichtborke , Penumbrafaden (10)\nBeruf:\nIngenieurskunst der Schattenlande (30)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n1\n15\n\n(2)\nBenutzen: Verschießt ein Paar aneinandergebundene Bomben direkt nach vorn, die sich um den ersten getroffenen Gegner wickeln, nach 5 Sek. explodieren und Gegnern in der Nähe dabei 13939 Feuerschaden zufügen. (5 Min Abklingzeit)\nBenötigt Ingenieurskunst der Schattenlande\n(1)" }
entries[310490] = { ["name"] = "Schwungumverteilungsstiefel", ["text"] = "Wirken in 2 sek. 3\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nZeitlich gesegnete Sprungfeder (10), Handvoll Laestritbolzen (20), Phaedrumerz (10), Gramleder (15), Schleierstoff (20)\nBeruf:\nIngenieurskunst der Schattenlande (65)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n2\n75\n\nWird bei Benutzung gebunden\nBenutzen: Leitet einen beträchtlichen Teil des Fallschadens, den Ihr bei Eurem nächsten Sturz erleiden würdet, auf Gegner in der Nähe um. Hält 10 Sek. lang an.\n\nKann nicht in Instanzen verwendet werden. (5 Min Abklingzeit)\nBenötigt Ingenieurskunst der Schattenlande\n(1)\n\"Ermöglicht Euch das Ausführen einer superheroischen Landung!\"" }
entries[310492] = { ["name"] = "Gravimetrische Störkanone", ["text"] = "Wirken in 2 sek. 3\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nWurmdurchsetztes Getriebe (3), Zeitlich gesegnete Sprungfeder (3), Handvoll Laestritbolzen (20), Poröses Scheuermittel (20), Soleniumerz (10), Heiliger Splitter (5)\nBeruf:\nIngenieurskunst der Schattenlande (60)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n2\n50\n\nWird bei Benutzung gebunden\nBenutzen: Destabilisiert die Schwerkraft um einen Zielort, was 10 Sek. lang die Bewegung von Gegnern in der Nähe behindert, sie in zufällige Richtungen schleudert oder sie in die Luft stößt...\n\nsofern keine Fehlzündung eintritt.\nBenötigt Ingenieurskunst der Schattenlande\n(1)\n\"Wird gelegentlich als \"Schwarzes-Loch-Kanone\" bezeichnet, was jedoch ein unzutreffender Name ist. Eigentlich ist es eher ein Artilleriegeschütz.\"" }
entries[310493] = { ["name"] = "533L3N-F4LL3", ["text"] = "Wirken in 2 sek. 3\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nWurmdurchsetztes Getriebe (3), Zeitlich gesegnete Sprungfeder (5), Handvoll Laestritbolzen (10), Phaedrumerz (10), Seelenstaub (5)\nBeruf:\nIngenieurskunst der Schattenlande (50)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n2\n\nWird bei Benutzung gebunden\nBenutzen: Platziert ein Eindämmungsgerät auf dem Boden, das nach seiner Scharfmachung aktiviert wird, wenn ein Gegner darauf tritt. Der Gegner wird dann für 1 Min. gebannt.\n\nEs sei denn, es tritt eine Fehlzündung ein.\n\nVerringerte Wirksamkeit gegen Spielercharaktere. (3 Min Abklingzeit)\nBenötigt Ingenieurskunst der Schattenlande\n(1)\n\"Mit wem werdet Ihr kommunizieren?!\"" }
entries[310495] = { ["name"] = "Dimensionswechsler", ["text"] = "Wirken in 2 sek.\nBenötigt Gürtel\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nWurmdurchsetztes Getriebe , Handvoll Laestritbolzen (10), Sinvyrerz (3), Umbryl , Unsterblichkeitssplitter\nBringt dauerhaft einen technomagischen Realitätsverzerrer an Eurem Gürtel an. Damit könnt Ihr Euch außerhalb des Kampfes unsichtbar machen.\nBeruf:\nIngenieurskunst der Schattenlande (45)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n1\n75" }
entries[310496] = { ["name"] = "Elektrosprung", ["text"] = "Wirken in 2 sek.\nBenötigt Gürtel\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nWurmdurchsetztes Getriebe , Handvoll Laestritbolzen (10), Soleniumerz (3), Oribrant , Unsterblichkeitssplitter\nBringt dauerhaft ein technomagisches Raumzeitfaltgerät an Eurem Gürtel an. Damit könnt Ihr Euch sofort über eine kurze Distanz in eine zufällige Richtung teleportieren.\nBeruf:\nIngenieurskunst der Schattenlande (45)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n1\n75" }
entries[310497] = { ["name"] = "Schadensvergelter", ["text"] = "Wirken in 2 sek.\nBenötigt Gürtel\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nWurmdurchsetztes Getriebe , Handvoll Laestritbolzen (10), Oxxeinerz (3), Wutauge , Unsterblichkeitssplitter\nBringt dauerhaft ein technomagisches Fluxrelais an Eurem Gürtel an. Dieses lässt bei Aktivierung mehrere kleine Klingenwaffen um Euch herumschweben, die Angreifern Schaden zufügen.\nBeruf:\nIngenieurskunst der Schattenlande (45)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n1\n75" }
entries[310499] = { ["name"] = "Leerenmiasma", ["text"] = "Unbegrenzte Reichweite\nSofort\nDas Tentakel von Drest'agath erzeugt innerhalb von 12 Metern eine Miasmawolke, die allen Gegnern darin alle 3 Sek. 4690 Schattenschaden zufügt. Gegner können Ziele im Effektbereich von ' Leerenmiasma ' nicht von außerhalb anvisieren und umgekehrt." }
entries[310501] = { ["name"] = "Flexible Ektoplasmabrille", ["text"] = "Wirken in 2 sek. 3\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nWurmdurchsetztes Getriebe (3), Handvoll Laestritbolzen (5), Umbryl (2), Schleierstoff (10)\nOptionale Reagenzien:\nBeruf:\nIngenieurskunst der Schattenlande (85)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n5\n25\n\nFlexible Ektoplasmabrille\nWird beim Aufheben gebunden\nKopf Stoff\n12 Rüstung\n+18 Intelligenz\n+27 Ausdauer\n+ 18 Zufallswert 1\n+ 18 Zufallswert 2\nHaltbarkeit 85 / 85\nAnlegen: Erhöht Eure Ingenieurskunst der Schattenlande um 20.\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\n60\nBenötigt Ingenieurskunst der Schattenlande\n(1)" }
