entries[310525] = { ["name"] = "Zeitlich gesegnete Sprungfeder", ["text"] = "Wirken in 1.5 sek.\nTools: Schmiedehammer\nReagenzien:\nPoröses Scheuermittel (3), Laestriterz (5), Leuchtender Fluxus (2)\nBeruf:\nIngenieurskunst der Schattenlande (15)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n50\n\nZeitlich gesegnete Sprungfeder\n(2)\nHandwerksmaterial\n\"Wird von Ingenieuren bei der Herstellung filigraner Gegenstände verwendet.\"\nGeplündert von: Instabile Speichereinheit\nDropchance: 3.83%" }
entries[310526] = { ["name"] = "Wurmdurchsetztes Getriebe", ["text"] = "Wirken in 1.5 sek.\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nHandvoll Laestritbolzen (4), Poröses Scheuermittel (5), Laestriterz (3), Maschinenöl\nBeruf:\nIngenieurskunst der Schattenlande (25)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n1\n\nWurmdurchsetztes Getriebe\n(2)\nHandwerksmaterial\n\"Wird von Ingenieuren bei der Herstellung extrem komplexer Gegenstände verwendet.\"\nGeplündert von: Instabile Speichereinheit\nDropchance: 1.99%" }
