entries[310530] = { ["name"] = "Ergebener Geist", ["text"] = "Sofort\nErhaltet alle 5 Sek. 'Ergebener Geist, wodurch Euer nächster Einsatz von ' Schnellheilung ' um zusätzlich 153 Gesundheit heilt. Bis zu 3-mal stapelbar.\n\nEinzigartig: Verderbniswiderstand um 10 erhöht." }
