entries[310533] = { ["name"] = "Optischer Zielvergrößerer", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nWurmdurchsetztes Getriebe , Handvoll Laestritbolzen (5), Wutauge , Oribrant\nErschafft eine dauerhafte Waffenverzauberung, die nur auf Schusswaffen, Bögen oder Armbrüste angewendet werden kann.\nBeruf:\nIngenieurskunst der Schattenlande (75)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n3\n50\n\nOptischer Zielvergrößerer\nBenutzen: Bringt dauerhaft ein Zielfernrohr an einer Distanzwaffe an, sodass manchmal Euer kritischer Trefferwert 12 Sek. lang um 824 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen dieser Vorrichtung an eine Distanzwaffe wird diese seelengebunden.\n51\n\"Bämm. Kopfschuss.\"" }
entries[310534] = { ["name"] = "Infragrünes Reflexzielfernrohr", ["text"] = "Wirken in 2 sek.\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nWurmdurchsetztes Getriebe , Handvoll Laestritbolzen (5), Oribrant (2)\nErschafft eine dauerhafte Waffenverzauberung, die nur auf Schusswaffen, Bögen oder Armbrüste angewendet werden kann.\nBeruf:\nIngenieurskunst der Schattenlande (75)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n3\n50\n\nInfragrünes Reflexzielfernrohr\nBenutzen: Bringt dauerhaft ein Zielfernrohr an einer Distanzwaffe an, sodass manchmal Euer Tempo 12 Sek. lang um 824 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen dieser Vorrichtung an eine Distanzwaffe wird diese seelengebunden.\n51\n\"Vor mir kann sich niemand verstecken.\"" }
entries[310535] = { ["name"] = "Wurmlochgenerator: Schattenlande", ["text"] = "Wirken in 2 sek. 3\nTools: Bogenlichtschraubenschlüssel , Schmiedehammer\nReagenzien:\nWurmdurchsetztes Getriebe (3), Zeitlich gesegnete Sprungfeder (7), Handvoll Laestritbolzen (20), Elethiumerz (3), Soleniumerz (10), Oxxeinerz (10), Phaedrumerz (10), Sinvyrerz (10)\nVerkäufer:\nDar Vattish\nZone:\nOribos\nDie Unvergängliche Armee - Wohlwollend\nKosten:\n1.350\n\nVerkäufer:\nNalcorn Talsen\nZone:\nMaldraxxus\nDie Unvergängliche Armee - Wohlwollend\nKosten:\n1.350\n\nWurmlochgenerator: Schattenlande\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Öffnet ein Wurmloch, das es dem Benutzer ermöglicht, schnell an einen von mehreren Fixpunkten innerhalb der Schattenlande zu reisen. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst der Schattenlande\n(1)\n\"VORSICHT: Ungenaue Befolgung der Sicherheitsrichtlinien kann Folgen haben, wie... Doppeltod? Turbotod? Lebendigkeit?\"" }
entries[310536] = { ["name"] = "Präzisionslebenskraftumkehrer", ["text"] = "Wirken in 3 sek. 2\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nLaestriterz (4), Zeitlich gesegnete Sprungfeder , Handvoll Laestritbolzen (4), Zwielichtborke (8)\nOptionale Reagenzien:\nBeruf:\nIngenieurskunst der Schattenlande (35)\nLehrer:\nMaschinist Au'gur\nZone:\nOribos\nKosten:\n1\n30\n\nPräzisionslebenskraftumkehrer\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n13 - 25 Schaden Geschwindigkeit 3.00\n(6.3 Schaden pro Sekunde)\n+9 Beweglichkeit\n+13 Ausdauer\n+ 9 Zufallswert 1\n+ 9 Zufallswert 2\nHaltbarkeit 85 / 85\n50\n\"Sorgt mit hoher Effizienz dafür, dass gegnerische Kämpfer weniger gesund werden.\"" }
